190	// A layered parallax field drifting rightward -- deeper (bigger, brighter)
191	// stars move faster. Returns its own teardown. Ported from the approved
192	// prototype so the shipped page matches it exactly.
193	function startDrift(canvas: HTMLCanvasElement): () => void {
194	  const ctx = canvas.getContext("2d");
195	  if (ctx === null) return () => {};
196	  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
197	  let w = 0;
198	  let h = 0;
199	  let raf = 0;
200	  let stars: Star[] = [];
201	
202	  function size() {
203	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
204	    w = canvas.clientWidth;
205	    h = canvas.clientHeight;
206	    canvas.width = w * dpr;
207	    canvas.height = h * dpr;
208	    ctx!.setTransform(dpr, 0, 0, dpr, 0, 0);
209	  }
210	
211	  function build() {
212	    size();
213	    const count = Math.min(300, Math.floor((w * h) / 3600));
214	    stars = [];
215	    for (let i = 0; i < count; i++) {
216	      const depth = Math.random();
217	      stars.push({
218	        x: Math.random() * w,
219	        y: Math.random() * h,
220	        size: 0.5 + depth * 1.6,
221	        base: 0.1 + depth * 0.45,
222	        sp: 0.05 + depth * 0.22,
223	        tw: Math.random() * 6.28,
224	        hot: Math.random() < 0.04,
225	      });
226	    }
227	  }
228	
229	  function frame(t: number) {
230	    const time = t / 1000;
231	    ctx!.clearRect(0, 0, w, h);
232	    for (const s of stars) {
233	      if (!reduce) {
234	        s.x += s.sp;
235	        if (s.x > w + 2) s.x = -2;
236	      }
237	      const tw = reduce ? 1 : 0.7 + 0.3 * Math.sin(time * 1.3 + s.tw);
238	      ctx!.beginPath();
239	      ctx!.arc(s.x, s.y, s.size, 0, 6.2832);
240	      if (s.hot) {
241	        ctx!.fillStyle = `rgba(10,132,255,${s.base + 0.2})`;
242	        ctx!.shadowColor = "rgba(10,132,255,.8)";
243	        ctx!.shadowBlur = 6;
244	      } else {
245	        ctx!.fillStyle = `rgba(255,255,255,${s.base * tw})`;
246	        ctx!.shadowBlur = 0;
247	      }
248	      ctx!.fill();
249	    }
250	    ctx!.shadowBlur = 0;
251	    if (!reduce) raf = requestAnimationFrame(frame);
252	  }
253	
254	  function onResize() {
255	    build();
256	    if (reduce) frame(0);
257	  }
258	
259	  build();
260	  if (reduce) frame(0);
261	  else raf = requestAnimationFrame(frame);
262	  window.addEventListener("resize", onResize);
263	
264	  return () => {
265	    cancelAnimationFrame(raf);
266	    window.removeEventListener("resize", onResize);
267	  };
268	}
